def _resolve_api_timeout(default: float = 600.0) -> float:
    """Honour GRAPHIFY_API_TIMEOUT env var override, else use default (seconds)."""
    raw = os.environ.get("GRAPHIFY_API_TIMEOUT", "").strip()
    if raw:
        try:
            v = float(raw)
            if v > 0:
                return v
        except ValueError:
            pass
    return default

